INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('255af0c0687034b5342f','AMEDEX 2025 GIT 41-75.pdf','82','Gastroenterology/Surgery','A 43-year-old man presents to your General Practice with midline abdominal swelling, as shown in the photograph. The swelling is not painful but feels uncomfortable. It significantly decreases when lying down and accentuates when he coughs or raises his legs or shoulders while supine. On physical examination, the lump feels soft and non-tender. Which one of the following is the most appropriate next step in management?',NULL,'A','Option A Is correct

The photograph shows a midline swelling starting
from the umbilicus and extending halfway between
the umbilicus and the xiphoid process of the
sternum. The appearance, history, and physical
findings make abdominal recti diastasis (ARD) the

most likely diagnosis.

Abdominal rectus diastasis is a condition in which
an abnormal distance separates the abdominal
muscles due to the widening of the linea alba,
which causes the abdominal content to bulge. The
rectus fascia is intact, and the condition should not
be confused with a ventral hernia. Rectus diastasis
can be congenital but is most commonly acquired
during pregnancies and/or larger weight gain,
which causes laxity of the linea alba.

ARD presents with visible bulging on exertion or
when the intrabdominal pressure increases
(Valsalva maneuvers, coughing, straining, etc.)
DRA often develops around the umbilicus but can
also occur anywhere between the xiphoid and the

pubic bone.

It is a common condition in pregnancy, with an
incidence as high as 66% in the third trimester. In
30-60% of cases, it persists post-partum. Not all

patients with abdominal rectus diastasis are

symptomatic. Symptoms, if present, include paj
and discomfort in the abdomen, musculoskele

problems like SGPHCTMMStauimry anu ombar back

It is a common condition in pregnancy, with an

incidence as high as 66% in the third trimester. In
30-60% of cases, it persists post-partum. Not all
patients with abdominal rectus diastasis are
symptomatic. Symptoms, if present, include pain
and discomfort in the abdomen, musculoskeletal
problems like pelvic instability and lumbar back
pain, and urogynecological symptoms such as
urinary incontinence, fecal incontinence, and pelvic
organ prolapse. In addition, patients with rectus
diastasis also experience lower perception of body
image, lower body satisfaction, and lower quality of

life compared with the general population.

Patients with symptoms should receive treatment.
Although the efficacy has not been studied
adequately, treatment starts with physiotherapy of

abdominal wall muscles.

lf months of physiotherapy fail to improve the
condition, surgical repair comes next. The
procedure can be performed via classic
abdominoplasty (option E) or endoscopic surgery
and defect stabilization (option D).

Hernioplasty and mesh insertion (option C) is
used for hernias. DRA is not a true hernia.

An abdominal (hernia) belt or truss (option
B) keeps the content of a hernia inside the
abdominal wall by applying pressure over the
defect. They are used to relieve hernia symptoms,
bridge the surgery, or provide additional support
during recovery from the surgery. They are not

used as a treatment modality of DRA.','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","supporting_pages":[82,83,84,85,86],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch006-2026-09-24","parser_mode":"human_visual_review_batch006","text_method":"manual_visual_plus_context","visual_asset":"manual_review_assets/AMEDEX_2025_GIT_41-75__5a77127663d0/page_00084.jpg","asset_preview_url":"https://drive.google.com/file/d/17KI6RNL8d0jRCj2-jsttrYoMNbRmlOg7/preview"}','manual_review_assets/AMEDEX_2025_GIT_41-75__5a77127663d0/page_00084.jpg','https://drive.google.com/thumbnail?id=17KI6RNL8d0jRCj2-jsttrYoMNbRmlOg7&sz=w1600','text',NULL,'needs_verification','[]','low','{"record_id":"255af0c0687034b5342f","record_type":"visual_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_year":2025,"source_page":82,"supporting_pages":[82,83,84,85,86],"source_qid":null,"domain_hint":"Gastroenterology/Surgery","stem":"A 43-year-old man presents to your General Practice with midline abdominal swelling, as shown in the photograph. The swelling is not painful but feels uncomfortable. It significantly decreases when lying down and accentuates when he coughs or raises his legs or shoulders while supine. On physical examination, the lump feels soft and non-tender. Which one of the following is the most appropriate next step in management?","options":{},"options_mode":"text","source_answer":"A","source_explanation":"Option A Is correct\n\nThe photograph shows a midline swelling starting\nfrom the umbilicus and extending halfway between\nthe umbilicus and the xiphoid process of the\nsternum. The appearance, history, and physical\nfindings make abdominal recti diastasis (ARD) the\n\nmost likely diagnosis.\n\nAbdominal rectus diastasis is a condition in which\nan abnormal distance separates the abdominal\nmuscles due to the widening of the linea alba,\nwh