hernias. DRA is not a true hernia.\n\nAn abdominal (hernia) belt or truss (option\nB) keeps the content of a hernia inside the\nabdominal wall by applying pressure over the\ndefect. They are used to relieve hernia symptoms,\nbridge the surgery, or provide additional support\nduring recovery from the surgery. They are not\n\nused as a treatment modality of DRA.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch006","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch006-2026-09-24","visual_asset":"manual_review_assets/AMEDEX_2025_GIT_41-75__5a77127663d0/page_00084.jpg","merge_record_ids":[],"manual_review_batch":"006","manual_review_source_key":"","stem_hash":"52d9e3d54d478a27bfc7514f6332980e7d4091a40f25ff2869128dfcf312227b","visual_assets":["manual_review_assets/AMEDEX_2025_GIT_41-75__5a77127663d0/page_00084.jpg"]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
