INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c8ffb3247523eef952c6','AMEDEX 2025 GIT 41-75.pdf','87','Gastroenterology','A 2/-year-old woman of Jewish descent
presents with jaundice for the last week. She
reports recently “battling a stubborn cold” and
sometimes has abdominal pain. She has no
other complaints; her medical history is only
