INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('95a9d57232b297059c22','AMEDEX 2025 GIT 41-75.pdf','157','Gastroenterology','>»
JVVOVECT, es ~~ WC
observation would be best management here in
an attempt to avoid the high rates of
complications associated with surgical drainage.
If the symptoms were more pronounced,
intolerable, or indicative of more serious
complications, surgical drainage (open surface
drainage) would have been the option of choice.
Percutaneous catheter drainage has a
low success rate and high recurrent rates. It is
never considered for the treatment of a
pancreatic pseudocyst. However, in infected
pseudocysts it is the procedure of choice for
Sampling and examining the material as the
most appropriate initial step.
Reference(s) ° HPB- Pancreatic pseudocysts — w
