INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2dbfff364a7ffc6f392a','AMEDEX 2025 GIT 76-100.pdf','11','Gastroenterology/Surgery','Ten years ago, a 75-year-old man underwent a successful right hemicolectomy for colon cancer, followed by chemotherapy after the cancer was found to be Duke C stage. Now, he has presented for surveillance. He has no specific complaint, and the physical examination is normal. Which of the following would be the investigation of choice for him?',NULL,'B','Option B Is correct

A colonoscopy should be performed one year after
the resection of sporadic cancer unless a complete
post-operative colonoscopy has been performed
sooner. Recommendations for familial
adenomatous polyposis (FAP) and hereditary
nonpolyposis colorectal cancers (HNPCC) are

different from sporadic cancers.

lf a perioperative colonoscopy performed at one
year reveals advanced adenoma, the next
colonoscopy should be performed in three years. If
the colonoscopy performed at one year is normal
or identifies no advanced adenomas, the next
colonoscopy should be performed in five years.
Since this man has not had a colonoscopy in the

past ten years, he should undergo one now.

Apart from colonoscopy according to the above
recommendations, patients undergoing either local
excision (including transanal endoscopic
microsurgery) of rectal cancer or advanced
adenomas or ultra-low anterior resection for rectal
cancer should be considered for periodic
examination of the rectum at 6-month intervals for
2-3 years with digital rectal examination, rigid
proctoscopy, flexible proctoscopy, and/or rectal
endoscopic ultrasound. These examinations are

considered to be independent of the colonoscopic

examination schedule described above.

Other tests tee=eres=ee=eeee=eerrg this period

Other tests that may be used during this period

for early detection of metastases may include:

e Chest X-ray

e CEA (carcinoembryonic antigen) —
diagnostically nonspecific but useful for
monitoring recurrence.

e PET scan (distant metastases will light up on
PET scan)

e Pelvic/abdominal CT scan

Abdominal CT scan (option A) and CEA (option
D) are acceptable surveillance options but not as
crucial as colonoscopy.

(Option E) Sigmoidoscopy cannot visualize
beyond the sigmoid colon. Patients with a history
of colon cancer need to have visualization of their
entire colon for possible tumors or premalignant
lesions by colonoscopy.

Reference(s) ° UpToDate - Surveillance after col
orectal cancer resection

Hide the correct option

Hide explanations','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","supporting_pages":[11,12,13],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch007-2026-09-24","parser_mode":"human_visual_review_batch007","text_method":"manual_visual_plus_context","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"2dbfff364a7ffc6f392a","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_year":2025,"source_page":11,"supporting_pages":[11,12,13],"source_qid":null,"domain_hint":"Gastroenterology/Surgery","stem":"Ten years ago, a 75-year-old man underwent a successful right hemicolectomy for colon cancer, followed by chemotherapy after the cancer was found to be Duke C stage. Now, he has presented for surveillance. He has no specific complaint, and the physical examination is normal. Which of the following would be the investigation of choice for him?","options":{},"options_mode":"text","source_answer":"B","source_explanation":"Option B Is correct\n\nA colonoscopy should be performed one year after\nthe resection of sporadic cancer unless a complete\npost-operative colonoscopy has been performed\nsooner. Recommendations for familial\nadenomatous polyposis (FAP) and hereditary\nnonpolyposis colorectal cancers (HNPCC) are\n\ndifferent from sporadic cancers.\n\nlf a perioperative colonoscopy performed at one\nyear reveals advanced adenoma, the next\ncolonoscopy should be performed in three years. If\nthe colonoscopy performed at one year is normal\nor identifies no advanced adenomas, the next\ncolonoscopy should be performed in five years.\nSince this man has not had a colonoscopy in the\n\npast ten years, he should undergo one now.\n\nApart from colonoscopy according to the above\nrecommendations, patients undergoing either local\nexcision (including transanal endoscopic\nmicrosurgery) of rectal cancer or advanced\nadenomas or ultra-low anterior resection for rectal\ncancer should be considered for periodic\nexamination of the rectum at 6-month intervals for\n2-3 years with digital rectal examination, rigid\nproctoscopy, flexible proctoscopy, and/or rectal\nendoscopic ultrasound. These examinations are\n\nconsidered to be independent of the colonoscopic\n\nexamination schedule described above.\n\nOther tests tee=eres=ee=eeee=eerrg this period\n\nOther tests that may be used during this period\n\nfor early detection of metastases may include:\n\ne Chest X-ray\n\ne CEA (carcinoembryonic antigen) —\ndiagnostically nonspecific but useful for\nmonitoring recurrence.\n\ne PET scan (distant metastases will light up on\nPET scan)\n\ne Pelvic/abdominal CT scan\n\nAbdominal CT scan (option A) and CEA (option\nD) are acceptable surveillance options but not as\ncrucial as colonoscopy.\n\n(Option E) Sigmoidoscopy cannot visualize\nbeyond the sigmoid colon. Patients with a history\nof colon cancer need to have visualization of their\nentire colon for possible tumors or premalignant\nlesions by colonoscopy.\n\nReference(s) ° UpToDate - Surveillance after col\norectal cancer resection\n\nHide the correct option\n\nHide explanations","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch007","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch007-2026-09-24","visual_asset":null,"merge_record_ids":[],"manual_review_batch":"007","manual_review_source_key":"","stem_hash":"750b038f8db7f94069b33616c62f58af1bd32a1acb343edd18385560bb8716b8"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,