INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('61a8fcda0de8a1d938f7','AMEDEX 2025 GYNAECOLOGY (1).pdf','31','Gynaecology','ee oe _s
A 20-year-old woman presents to your
practice with complaints of episodes of
erratic vaginal bleeding for the
past four months after she started taking
combined oral contraceptive pills
(Microgynon 30). She is sexually active and
uses condoms for the prevention of sexually
transmitted infections as well. Which of the
following would be the most appropriate
