INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5247af51f8e4bce5d99f','AMEDEX 2025 GYNAECOLOGY (1).pdf','76','Gynaecology/Dermatology','A 54-year-old woman presents to your clinic with a complaint of a vulvar lesion associated with severe itching. Her problem started nearly six months ago and has progressed in severity. She has been menopausal since the age of 50 years. On examination, atrophic white plaques are evident, as well as excoriation marks over and around the vulva. The labia minora is slightly atrophic, and there is introitus stenosis. The vaginal examination is normal. The appearance of the vulva is shown in the accompanying photograph. Which one of the following is the most appropriate option for the treatment of this patient?',NULL,'B','Option B Is correct

The clinical findings of pruritic white vulvar
plaques, in the absence of vaginal symptoms and
signs, make genital lichen sclerosus (LS) the most
likely diagnosis.

LS is a chronic inflammatory dermatosis of
unknown etiology. The disease most commonly
affects the genitalia but can occur at any skin site
(extragenital lichen sclerosus). Balanitis xerotica
obliterans is an outdated term used to describe the
LS of glans penis. Lichen sclerosus can occur in
males or females of any age. In females, however,
there are two peaks of onset during prepubertal
and perimenopausal/postmenopausal ages, both
of which are estrogen-deficient states; however,
the relationship between LS and estrogen
deficiency is unclear. In males, it is more common

between puberty and age 60 years.

Typical clinical presentation is with white, often
atrophic, plaques associated with pruritus and pain
that result in genital scarring and adhesions. The
most common complaint in vulvar lichen sclerosus
is progressive pruritus that can be followed by
dyspareunia, dysuria, or genital bleeding. Female
genital lesions may be confined to the labia majora
but usually involve and eventually obliterate the
labia minora and stenose the introitus. Often, an
hourglass, butterfly, or figure-8 pattern involve

périvaginal and perianal areas, with minimal

INVOIVEMeENt 0 febinempeuhnetHtememeiAe CN.

perivaginal and perianal areas, with minimal

involvement of the perineum in between.

Penile LS is associated with sexual/urinary
dysfunction. It is usually preceded by pruritus but
may present with sudden phimosis of previously
retractable foreskin, and urinary obstruction can

result.

Extragenital lichen sclerosus (LS) may be
asymptomatic (approximately one-third of cases)
or itch or tender.

NOTE - With genital LS in women, there is an
increased risk of squamous cell carcinoma
(<5%). Progression to malignancy in genital LS
in men is rare.

First-line therapy for LS includes patient education
and super-potent topical corticosteroids (e.g.,
clobetasol propionate). Prolonged use of potent
corticosteroids does not result in atrophy of the
labia minora and clitoris, owing to the resistant
nature of their modified mucous membranes.
However, perianal and hair-baring areas (e.g.,
labia majora) can atrophy within 2-3 weeks of use.
Intralesional corticosteroid injections are also

considered on occasion.

Second-line therapies include calcineurin
inhibitors, tacrolimus, and pimecrolimus, which can
be a helpful adjunct to topical corticosteroids for
maintenance.

Third-line therapies that could be considered |

treatment-resistant genital lichen sclerosus co

include topical Pore nrennolm, steroid iniections.','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (1).pdf","supporting_pages":[76,77,78,79,80],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch007-2026-09-24","parser_mode":"human_visual_review_batch007","text_method":"manual_visual_plus_context","visual_asset":"manual_review_assets/AMEDEX_2025_GYNAECOLOGY_1__d705016f12b9/page_00078.jpg","asset_preview_url":"https://drive.google.com/file/d/1hlnHvLWGC-QSHH1VMsWjHjRmLkVURQET/preview"}','manual_review_assets/AMEDEX_2025_GYNAECOLOGY_1__d705016f12b9/page_00078.jpg','https://drive.google.com/thumbnail?id=1hlnHvLWGC-QSHH1VMsWjHjRmLkVURQET&sz=w1600','text',NULL,'needs_verification','[]','low','{"record_id":"5247af51f8e4bce5d99f","record_type":"visual_mcq","source_file":"AMEDEX 2025 GYNAECOLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (1).pdf","source_year":2025,"source_page":76,"supporting_pages":[76,77,78,79,80],"source_qid":null,"domain_hint":"Gynaecology/Dermatology","stem":"A 54-year-old woman presents to your clinic with a complaint of a vulvar lesion associated with severe itching. Her problem started nearly six months ago and has progressed in severity. She has been menopausal since the age of 50 years. On examination, atrophic white plaques are evident, as well as excoriation marks over and around the vulva. The labia minora is slightly atrophic, and there is introitus stenosis. The vaginal examination is normal. The appearance of the vulva is shown in the accompanying photograph. Which one of the following is the most appropriate option for the treatment of this patient?","options":{},"options_mode":"text","source_answer":"B","source_explanation":"Option B Is correct\n\nThe clinical findings of pruritic white vulvar\nplaques, in the absence of vaginal symptoms and\nsigns, make genital lichen sclerosus (LS) the most\nlikely diagnosis.\n\nLS is a chronic inflammatory dermatosis of\nunknown etiology. The disease most commonly\naffects the genitalia but can occur at any skin site\n(extragenital lichen sclerosus). Balanitis xerotica\nobliterans is an outdated term used to describe the\nLS of glans penis. Lichen sclerosus can occur in\nmales or females of any age. In females, however,\nthere are two peaks of onset during prepubertal\nand perimenopausal/postmenopausal ages, both\nof which are estrogen-deficient states; however,\nthe relationship between LS and estrogen\ndeficiency is unclear. In males, it is more common\n\nbetween puberty and age 60 years.\n\nTypical clinical presentation is with white, often\natrophic, plaques associated with pruritus and pain\nthat result in genital scarring and adhesions. The\nmost common complaint in vulvar lichen sclerosus\nis progressive pruritus that can be followed by\ndyspareunia, dysuria, or genital bleeding. Female\ngenital lesions may be confined to the labia majora\nbut usually involve and eventually obliterate the\nlabia minora and stenose the introitus. Often, an\nhourglass, butterfly, or figure-8 pattern involve\n\npérivaginal and perianal areas, with minimal\n\nINVOIVEMeENt 0 febinempeuhnetHtememeiAe CN.\n\nperivaginal and perianal areas, with minimal\n\ninvolvement of the perineum in between.\n\nPenile LS is associated with sexual/urinary\ndysfunction. It is usually preceded by pruritus but\nmay present with sudden phimosis of previously\nretractable foreskin, and urinary obstruction can\n\nresult.\n\nExtragenital lichen sclerosus (LS) may be\nasymptomatic (approximately one-third of cases)\nor itch or tender.\n\nNOTE - With genital LS in women, there is an\nincreased risk of squamous cell carcinoma\n(<5%). Progression to malignancy in genital LS\nin men is rare.\n\nFirst-line therapy for LS includes patient education\nand super-potent topical corticosteroids (e.g.,\nclobetasol propionate). Prolonged use of potent\ncorticosteroids does not result in atrophy of the\nlabia minora and clitoris, owing to the resistant\nnature of their modified mucous membranes.\nHowever, perianal and hair-baring areas (e.g.,\nlabia majora) can atrophy within 2-3 weeks of use.\nIntralesional corticosteroid injections are also\n\nconsidered on occasion.\n\nSecond-line therapies include calcineurin\ninhibitors, tacrolimus, and pimecrolimus, which can\nbe a helpful adjunct to topical corticosteroids for\nmaintenance.\n\nThird-line therapies that could be considered |\n\ntreatment-resistant genital lichen sclerosus co\n\ninclude topical Pore nrennolm, steroid iniections.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch007","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch007-2026-09-24","visual_asset":"manual_review_assets/AMEDEX_2025_GYNAECOLOGY_1__d705016f12b9/page_00078.jpg","merge_record_ids":[],"manual_review_batch":"007","manual_review_source_key":"","stem_hash":"1316579a9ca7c9c3bd2c034c5c4f77123b0e5e0b493c5049a4073f76b823bdef","visual_assets":["manual_review_assets/AMEDEX_2025_GYNAECOLOGY_1__d705016f12b9/page_00078.jpg"]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excl