INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('64b6c7d43f936e4fc3d2','AMEDEX 2025 GYNAECOLOGY (1).pdf','93','Gynaecology','An 18-year-old girl comes to see you ata
medical centre. She just has become sexually
active with her new boyfriend. She is
concerned about her risk of cervical cancer
