INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a760fbd59d35068bbeb1','AMEDEX 2025 GYNAECOLOGY (2).pdf','5','Gynaecology','A 37-year-old woman presents with
secondary amenorrhea of 7 months duration.
She has a body mass index (BMI) of 24. On
laboratory studies, she has an FSH level of 55
U/L (2-8U/L in luteal phase; >25U/L in
menopause), LH of 54 U/L, and estradiol, the
lower limit of normal. Serum prolactin level is
also normal. A urine pregnancy test excludes
pregnancy. On ultrasonography, each ovary
contains 3-4 cysts. She desires to become
pregnant in the future. Which one of the
following would be the most appropriate
