INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9d40d926f196957eefcb','AMEDEX 2025 GYNAECOLOGY (2).pdf','57','Gynaecology','Jessica, 51 years old, presents to your practice
with complaints of hot flashes, irritability, and
disturbed sleep for the past two months, which
have been progressively worsening. She had
